/* From Uiverse.io by nima-mollazadeh  - Tags: button */
.__UIV_SCOPE__ .btn-1,
.__UIV_SCOPE__ .btn-1 *,
.__UIV_SCOPE__ .btn-1 :after,
.__UIV_SCOPE__ .btn-1 :before,
.__UIV_SCOPE__ .btn-1:after,
.__UIV_SCOPE__ .btn-1:before {
  border: none;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .btn-1 {
  scale: 0.8;
  -webkit-tap-highlight-color: transparent;
  background-color: #000;
  background-image: none;
  color: #fff;
  font-family:
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    Segoe UI,
    Roboto,
    Helvetica Neue,
    Arial,
    Noto Sans,
    sans-serif,
    Apple Color Emoji,
    Segoe UI Emoji,
    Segoe UI Symbol,
    Noto Color Emoji;
  cursor: pointer;
  font-size: 100%;
  line-height: 1.5;
  margin: 0;
  padding: 2;
}

.__UIV_SCOPE__ .btn-1:disabled {
  cursor: default;
}

.__UIV_SCOPE__ .btn-1:-moz-focusring {
  outline: auto;
}

.__UIV_SCOPE__ .btn-1 svg {
  display: block;
  vertical-align: middle;
}

.__UIV_SCOPE__ .btn-1 [hidden] {
  display: none;
}

.__UIV_SCOPE__ .btn-1 {
  border: 1px solid;
  border-radius: 999px;
  box-sizing: border-box;
  display: block;
  font-weight: 900;
  overflow: hidden;
  padding: 1.2rem 3rem;
  position: relative;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .btn-1 .original {
  background: #ffffff;
  color: #000;
  display: grid;
  inset: 0;
  place-content: center;
  position: absolute;
  transition: transform 0.3s cubic-bezier(0.87, 0, 0.13, 1);
}

.__UIV_SCOPE__ .btn-1:hover .original {
  transform: translateY(100%);
}

.__UIV_SCOPE__ .btn-1 .letters {
  display: inline-flex;
}

.__UIV_SCOPE__ .btn-1 span {
  opacity: 0;
  transform: translateY(-15px);
  transition:
    transform 0.3s cubic-bezier(0.87, 0, 0.13, 1),
    opacity 0.3s;
}

.__UIV_SCOPE__ .btn-1 span:nth-child(2n) {
  transform: translateY(15px);
}

.__UIV_SCOPE__ .btn-1:hover span {
  opacity: 1;
  transform: translateY(0);
}

.__UIV_SCOPE__ .btn-1:hover span:nth-child(2) {
  transition-delay: 0.1s;
}

.__UIV_SCOPE__ .btn-1:hover span:nth-child(3) {
  transition-delay: 0.2s;
}

.__UIV_SCOPE__ .btn-1:hover span:nth-child(4) {
  transition-delay: 0.3s;
}

.__UIV_SCOPE__ .btn-1:hover span:nth-child(5) {
  transition-delay: 0.4s;
}

.__UIV_SCOPE__ .btn-1:hover span:nth-child(6) {
  transition-delay: 0.5s;
}
